let recordTeam='lotte',recordScope=0;const recordData=new Map(),recordPending=new Map(),recordErrors=new Map();
const renderScheduleView=render;render=function(){renderScheduleView();syncSidebarRecordSelection();};
function syncSidebarRecordSelection(){const showing=!$('records-view').hidden;$('all-teams').hidden=showing;if(!showing)return;document.querySelectorAll('#teams [data-team]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.team===recordTeam));b.onclick=()=>selectRecordTeam(b.dataset.team);});}
function selectRecordTeam(team){recordTeam=team;recordScope=0;renderRecords();loadRecords(team);}
function showView(view){const r=view==='records';$('schedule-view').hidden=r;$('records-view').hidden=!r;$('schedule-tab').setAttribute('aria-pressed',String(!r));$('records-tab').setAttribute('aria-pressed',String(r));if(r){renderRecords();loadRecords(recordTeam);}else render();}
$('schedule-tab').onclick=()=>showView('schedule');$('records-tab').onclick=()=>showView('records');
async function loadRecords(team,force=false){if(recordPending.has(team))return recordPending.get(team);if(!recordData.has(team)){try{const saved=JSON.parse(localStorage.getItem('matchday-records-progress-'+team));if(saved?.ok)recordData.set(team,saved);}catch{}if(team===recordTeam)renderRecords();}if(!force&&Date.now()-(recordData.get(team)?.loadedAt||0)<900000)return;
 const job=(async()=>{try{if(team===recordTeam)$('records-status').textContent='최신 기록 확인 중…';const r=await fetch('/.netlify/functions/records?team='+encodeURIComponent(team),{signal:AbortSignal.timeout(60000)});const data=await r.json();if(!r.ok||!data.ok)throw Error(data.error||'기록 조회 실패');data.loadedAt=Date.now();recordData.set(team,data);recordErrors.delete(team);try{localStorage.setItem('matchday-records-progress-'+team,JSON.stringify(data));}catch{}if(team===recordTeam)renderRecords();}catch(e){recordErrors.set(team,true);if(team===recordTeam){if(recordData.has(team))renderRecords();else{$('records-status').textContent='기록 연결 실패';$('record-body').innerHTML='<div class="empty">기록을 불러오지 못했어요. <button id="retry-records">다시 시도</button></div>';$('retry-records').onclick=()=>loadRecords(team,true);}}}finally{recordPending.delete(team);}})();recordPending.set(team,job);return job;}
function renderRecords(){syncSidebarRecordSelection();$('record-teams').innerHTML=teams.map(t=>`<button class="record-team" style="--color:${t.color}" aria-pressed="${t.id===recordTeam}" data-record-team="${t.id}"><img src="/logos/${t.id}.${t.id==='f1'?'svg':'png'}" alt="">${t.short}</button>`).join('');document.querySelectorAll('[data-record-team]').forEach(b=>b.onclick=()=>selectRecordTeam(b.dataset.recordTeam));const data=recordData.get(recordTeam);if(!data){$('record-body').innerHTML='<div class="empty">실제 기록을 불러오는 중이에요.</div>';return;}const c=data.competitions[recordScope]||data.competitions[0],t=teamOf(recordTeam),f1=recordTeam==='f1',ns=recordTeam==='ns';renderRecordStatus(data);
 if(c.mode==='progress'){renderProgress(c,t);return;}
 const rows=c.rows.map(r=>`<tr class="${r.id===c.own?.id&&!f1?'my-row':''}"><td>${r.rank??'—'}</td><td>${escapeHTML(r.name)}${r.detail?'<small> · '+escapeHTML(r.detail)+'</small>':''}</td><td>${r.points!==null&&r.points!==undefined?r.points+'점':r.wins!==null&&r.wins!==undefined?r.wins+'승 '+r.losses+'패':'—'}</td></tr>`).join('');
 const recent=c.recent.map(g=>`<div class="recent-row"><span class="result-pill ${g.result==='승'?'win':g.result==='패'?'loss':'draw'}">${g.result}</span><div>vs ${escapeHTML(g.opponent)}<small>${escapeHTML(g.date)}</small></div><span class="recent-score" data-score>${escapeHTML(g.score)}</span></div>`).join('');
 $('record-body').innerHTML=`<div class="record-summary"><div class="record-context"><div class="record-identity"><img src="/logos/${t.id}.${f1?'svg':'png'}" alt=""><div><h3>${t.name}</h3><small>${escapeHTML(c.name)}</small></div></div><label><select id="record-league" aria-label="기록 기준 대회">${data.competitions.map((x,i)=>`<option value="${i}" ${i===recordScope?'selected':''}>${escapeHTML(x.name)}</option>`).join('')}</select></label></div><div class="record-stats"><div class="record-stat"><small>${escapeHTML(c.rankLabel)}</small><strong>${f1?escapeHTML(c.own?.name):c.own?.rank?c.own.rank+'위':'미정'}</strong><p>${f1?'시즌 선두':'선택한 대회 기준'}</p></div><div class="record-stat"><small>${f1||ns?'포인트':'대회 전적'}</small><strong>${f1?c.own?.points+'점':escapeHTML(c.record)}</strong><p>${ns?'연간 챔피언십 포인트':'공식 출처 기준'}</p></div><div class="record-stat"><small>${f1?'참가 '+(c.id==='drivers'?'드라이버':'팀'):ns?'최근 경기':'승률'}</small><strong>${f1?c.rows.length:ns?c.recent.length+'경기':escapeHTML(c.rate)}</strong><p>${recordTeam==='lotte'?'무승부 제외':f1?'공식 순위표 기준':ns?'대회 전체 기준':'승리 ÷ 전체 경기'}</p></div></div></div><div class="record-columns"><section class="record-panel"><h3>${f1?'시즌 순위':'대회 순위'}</h3><table class="record-table"><thead><tr><th>순위</th><th>${f1?'이름':'팀'}</th><th>${f1||ns||['daegu','barca'].includes(recordTeam)?'포인트':'전적'}</th></tr></thead><tbody>${rows}</tbody></table></section><section class="record-panel"><h3>${f1?'시즌 기록 안내':'최근 5경기 · 선택 대회'}</h3>${f1?'<p>드라이버·팀 순위는 위에서 전환할 수 있어요. 승패 대신 누적 포인트를 표시합니다.</p>':recent||'<p>이 대회의 완료 경기 결과가 아직 없어요.</p>'}${c.note?'<p>'+escapeHTML(c.note)+'</p>':''}<p><a href="${escapeHTML(c.source)}" target="_blank" rel="noopener noreferrer">기록 출처</a></p></section></div>`;$('record-league').onchange=e=>{recordScope=Number(e.target.value);renderRecords();};}

function renderProgress(c,t){
 const recent=c.recent.map(g=>`<div class="recent-row"><div>vs ${escapeHTML(g.opponent)}<small>${escapeHTML(g.date)} · ${escapeHTML(g.competition)}<br>${escapeHTML(g.stage)}</small></div><span class="recent-score" data-score>${escapeHTML(g.score)} <span class="match-result result-${g.result==='승'?'win':g.result==='패'?'loss':'draw'}">${g.result}</span></span></div>`).join('');
 $('record-body').innerHTML=`<div class="record-summary"><div class="record-identity"><img src="/logos/${t.id}.png" alt=""><div><h3>${t.name}</h3><span class="competition-status ${c.rankLabel==='현재 참가 대회'?'status-current':'status-recent'}">${escapeHTML(c.rankLabel)}</span></div></div><div class="record-stats progress-stats"><div class="record-stat"><small>${escapeHTML(c.rankLabel)}</small><strong>${escapeHTML(c.name)}</strong></div><div class="record-stat"><small>${escapeHTML(c.stageLabel)}</small><strong>${escapeHTML(c.stage)}</strong></div><div class="record-stat"><small>최근 ${c.recent.length}경기 전적</small><strong>${escapeHTML(c.record)}</strong><p>대회 전체 기준</p></div></div></div><div class="record-columns"><section class="record-panel"><h3>다음 경기</h3><p class="progress-next">${escapeHTML(c.next)}</p><p class="record-note">${escapeHTML(c.note)}</p><a href="${escapeHTML(c.source)}" target="_blank" rel="noopener noreferrer">대회·경기 출처</a></section><section class="record-panel"><h3>최근 5경기 <small class="record-basis">· 전체 대회</small></h3>${recent||'<p>완료 경기 결과가 없어요.</p>'}</section></div>`;
}

function renderRecordStatus(data){
 const at=new Date(data.checkedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
 const failed=recordErrors.has(recordTeam),status=$('records-status');status.classList.toggle('update-delayed',failed);
 status.innerHTML=(failed?'업데이트 지연 · 마지막 확인 ':'마지막 확인 ')+escapeHTML(at)+(failed?' <button id="retry-records" type="button">다시 시도</button>':'');
 if(failed)$('retry-records').onclick=()=>loadRecords(recordTeam,true);
}
